*{box-sizing:border-box} :root{--ink:#080b10;--paper:#f0f1eb;--muted:#a0a5a9;--orange:#ff6035;--line:rgba(255,255,255,.15);--font:'DM Sans',sans-serif;--display:'Barlow Condensed',Impact,sans-serif} html,body{height:100%;margin:0} body{background:var(--ink);color:var(--paper);font-family:var(--font);overflow:hidden} button{color:inherit;font:inherit;cursor:pointer} #world{position:fixed;inset:0;width:100%;height:100%;z-index:0} .scene-vignette{position:fixed;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,rgba(6,9,13,.96) 0%,rgba(6,9,13,.88) 31%,rgba(6,9,13,.25) 63%,rgba(6,9,13,.10) 100%),linear-gradient(0deg,rgba(5,8,11,.85),transparent 40%,rgba(5,8,11,.32))} .topbar{height:88px;padding:0 6.1vw;display:flex;align-items:center;position:absolute;inset:0 0 auto;z-index:5;border-bottom:1px solid rgba(255,255,255,.11)} .brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--paper);font-family:var(--display);font-weight:800;font-size:21px;letter-spacing:1.6px;line-height:.85}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:2px solid var(--orange);color:var(--orange);font-size:23px;transform:skew(-10deg)}.brand-light{font-weight:500;color:#a8aaac}.brand small{display:block;font:600 8px var(--font);letter-spacing:3.1px;color:#9da1a3;margin-top:8px}.main-nav{display:flex;gap:42px;margin-left:10.4vw;height:100%;align-items:center}.nav-link{height:100%;background:none;border:0;color:#a4a8aa;font-size:10px;font-weight:700;letter-spacing:1.5px;position:relative;padding:0}.nav-link.active,.nav-link:hover{color:white}.nav-link.active:after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:var(--orange)}.player-stats{margin-left:auto;display:flex;align-items:center;gap:30px}.stat-pill{font-size:13px;font-weight:700;display:flex;align-items:center;gap:9px}.coin-icon{color:#f4b65b;font-size:13px;text-shadow:0 0 12px #f4a844}.profile{display:flex;align-items:center;gap:10px;position:r