0;border-right:1px solid rgba(255,255,255,.12);background:transparent;text-align:left;padding:20px 24px;position:relative;transition:background .2s}.feature-card:hover{background:rgba(255,255,255,.045)}.card-index{font-size:8px;letter-spacing:1.4px;color:#9da3a3}.card-index i{color:var(--orange);font-style:normal;padding:0 5px}.card-icon{position:absolute;right:20px;top:18px;color:var(--orange);font-size:19px}.garage-icon{font-size:23px}.card-title{display:block;font:700 21px/.91 var(--display);letter-spacing:.5px;margin-top:9px}.card-foot{position:absolute;bottom:17px;left:24px;right:20px;font-size:8px;letter-spacing:1.2px;color:#aeb3b1}.card-foot b{float:right;font-size:15px;color:var(--orange);line-height:8px}.weekly-card{padding:21px 24px;border-right:1px solid rgba(255,255,255,.12);position:relative}.weekly-label{font-size:8px;letter-spacing:1px;color:#c9cdca;display:flex;align-items:center;gap:8px}.weekly-label .live-dot{width:5px;height:5px}.weekly-card strong{display:block;font:700 24px/.86 var(--display);margin-top:12px;letter-spacing:.4px}.weekly-bottom{position:absolute;bottom:18px;font-size:8px;letter-spacing:1.1px;color:#9ba1a2}.weekly-bottom b{color:#fff;margin-left:7px}.challenge-arrow{position:absolute;left:245px;bottom:-3px;color:var(--orange);font-size:17px}.conditions{display:flex;flex-direction:column;padding:23px 24px;gap:10px}.conditions>span{font-size:8px;color:#9ca3a3;letter-spacing:1.3px}.conditions strong{font:700 15px var(--display);letter-spacing:1px}.sun-icon{font-style:normal;color:#f4b65b;font-size:19px;vertical-align:-2px;margin-right:5px}.conditions small{font-size:8px;letter-spacing:1px;color:#b3b9b8}.conditions small span{color:var(--orange);padding:0 4px}
/* garage and stage panels */
.panel-view{height:100vh;padding:135px 10vw 40px;overflow:auto;background:linear-gradient(110deg,rgba(7,10,14,.97),rgba(7,10,14,.87) 65%,rgba(7,10,14,.75))}.panel-header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:22px}.panel-header h2{font:800 54px/.9 var(--display);letter-spacing:.5px;margin-top:15px}.close-panel{border:1px solid var(--line);background:rgba(255,255,255,.04);width:38px;height:38px;font-size:23px;color:#c2c7c4}.garage-layout{display:grid;grid-template-columns:1.15fr .85fr;gap:8vw;padding:34px 0;max-width:1060px;margin:auto}.car-display{min-height:380px;position:relative;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,rgba(255,96,53,.14),transparent 55%),linear-gradient(140deg,rgba(255,255,255,.045),transparent 60%);border:1px solid rgba(255,255,255,.09)}.car-display:after{content:'';position:absolute;bottom:76px;left:8%;width:84%;height:1px;background:rgba(255,255,255,.22)}.garage-car-shape{--car-color:#cdd5d3;width:64%;height:92px;position:absolute;top:44%;left:18%;background:linear-gradient(180deg,rgba(255,255,255,.35),transparent 30%),linear-gradient(110deg,#5b6366,var(--car-color) 25%,#8d9695 70%,#40484a);clip-path:polygon(5% 52%,17% 47%,30% 18%,43% 5%,65% 8%,82% 35%,97% 48%,100% 80%,92% 91%,8% 91%,0 76%);filter:drop-shadow(0 20px 15px rgba(0,0,0,.7));transition:background .3s}.garage-car-shape:before,.garage-car-shape:after{content:'';position:absolute;bottom:0;width:23%;height:21px;background:#0a0c0f;border:5px solid #252b2e;border-radius:50%}.garage-car-shape:before{left:16%}.garage-car-shape:after{right:12%}.car-window{position:absolute;left:32%;top:12%;width:36%;height:38%;background:linear-gradient(120deg,#252f35,#0f171b);clip-path:polygon(18% 0,74% 0,100% 100%,0 100%)}.car-light{position:absolute;right:0;top:59%;width:9%;height:5px;background:#f1ddbd;box-shadow:0 0 12px #ffd9a3}.car-display-name{position:absolute;z-index: