r{width:200px;font-size:8px;letter-spacing:1.4px;color:#dde1db}.boost-track{height:4px;background:rgba(255,255,255,.32);margin:8px 0}.boost-track i{height:100%;width:100%;background:var(--orange);display:block;transition:width .1s}.boost-hint{color:#9ca3a1;font-size:7px}.controls-hint{font-size:8px;letter-spacing:1.2px;color:#c3c7c5;padding-bottom:4px}.controls-hint span{color:var(--orange);padding:0 6px}.touch-controls{display:none;gap:12px}.steer,.nitro-button{border:1px solid rgba(255,255,255,.35);background:rgba(8,11,15,.55);width:58px;height:55px;font-size:27px;color:white;touch-action:none}.nitro-button{color:var(--orange);font-size:20px;border-color:rgba(255,96,53,.65)}.race-overlay{position:absolute;inset:0;background:rgba(4,7,10,.72);backdrop-filter:blur(6px);display:none;align-items:center;justify-content:center}.race-overlay.show{display:flex}.overlay-card{width:min(380px,90vw);padding:38px;background:#11171b;border:1px solid rgba(255,255,255,.13);box-shadow:0 20px 80px #000}.overlay-card h2{font:800 62px/.82 var(--display);margin:20px 0 27px}.overlay-card .primary-btn{width:100%}.overlay-text-btn{display:block;margin:20px auto 0;border:0;background:none;color:#b6bcba;font-size:8px;letter-spacing:1.5px}.result-card{width:min(440px,92vw)}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:15px 0;margin:-7px 0 22px}.result-stats>div{display:flex;flex-direction:column;gap:7px}.result-stats span{font-size:7px;letter-spacing:1px;color:#a5adaa}.result-stats b{font:700 15px var(--display)}.result-stats .reward-text{color:#f4b65b}.toast{position:fixed;z-index:20;bottom:22px;left:50%;transform:translate(-50%,20px);background:#182024;border:1px solid var(--line);padding:12px 19px;font-size:10px;letter-spacing:.6px;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:800px){.topbar{height:68px;padding:0 20px}.brand{font-size:17px}.brand-mark{width:29px;height:29px;font-size:19px}.main-nav{margin-left:35px;gap:18px}.nav-link{font-size:8px;letter-spacing:.8px}.player-stats{gap:14px}.profile>span:not(.profile-avatar),.profile>i{display:none}.stat-pill{font-size:11px}.home-view{padding-top:68px}.scene-vignette{background:linear-gradient(90deg,rgba(6,9,13,.92),rgba(6,9,13,.35)),linear-gradient(0deg,rgba(5,8,11,.95),transparent 55%)}.hero-copy{left:7vw;top:19%;width:360px}.hero-copy h1{font-size:clamp(72px,12vw,100px)}.hero-art{inset:68px 0 170px 31%}.bottom-deck{left:20px;right:20px;grid-template-columns:1fr 1fr;height:145px}.feature-card{padding:13px 16px}.card-title{font-size:18px;margin-top:7px}.card-foot{left:16px;bottom:11px}.weekly-card,.conditions{display:none}.feature-card:nth-child(2){border-right:0}.card-index{font-size:7px}.car-spec{right:7vw}.panel-view{padding:105px 6vw 25px}.garage-layout{gap:4vw}.level-grid{grid-template-columns:repeat(8,1fr)}}
