op:17px;gap:12px}.garage-select-row{margin-top:18px}.car-picker{margin-top:16px}.level-worlds{overflow:auto}.world-tab{white-space:nowrap;padding:10px}.level-grid{grid-template-columns:repeat(6,1fr);gap:6px}.level-tile{font-size:12px}.overlay-card{padding:27px}.overlay-card h2{font-size:54px}}

